insert into public.country_occupation_profiles(profile_key,country_code,canonical_career_id,official_title,official_code_system,official_code_version,official_unit_group_code,currency,registration_required,registration_authority,registration_url,publication_status,source_checked_at,updated_at) values('AU:secondary-school-teacher','AU','secondary-school-teacher','Secondary School Teacher','OSCA','2024 v1.0','2513','AUD',true,'State and territory teacher regulatory authorities; AITSL is the migration skills assessing authority for ANZSCO 241411','https://www.aitsl.edu.au/teach/national-review-of-teacher-registration/framework-for-teacher-registration-in-australia','profile_ready','2026-08-09',now()) on conflict(profile_key) do update set official_title=excluded.official_title,official_code_system=excluded.official_code_system,official_code_version=excluded.official_code_version,official_unit_group_code=excluded.official_unit_group_code,currency=excluded.currency,registration_required=excluded.registration_required,registration_authority=excluded.registration_authority,registration_url=excluded.registration_url,publication_status=excluded.publication_status,source_checked_at=excluded.source_checked_at,updated_at=now();
insert into public.country_occupation_metric_snapshots(profile_key,as_of_date,employment_total,median_weekly_earnings,median_hourly_earnings,annualised_median_salary,all_occupations_median_weekly,part_time_share_pct,female_share_pct,median_age,average_full_time_hours,vacancies_three_month_avg,vacancy_period,vacancy_yoy_pct,employment_growth_5y_pct,employment_growth_10y_pct,shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at) values('AU:secondary-school-teacher','2026-05-01',null,null,null,null,1852,null,null,null,null,762.33333,'2026-05-01',-10.73,5.45,11.68,20,0,5,0,13,0,5,10,2,55,'career-opportunity-v1','provisional',jsonb_build_object('current_classification_scope','Current OSCA 251331 Secondary School Teacher is an exact Skill Level 1 occupation. Special Education Teachers are explicitly excluded.','current_anzsco_mapping','The current skilled occupation instrument lists Secondary School Teacher as ANZSCO 241411 with AITSL. CampCareer corrects the pre-existing staging value 241311 to 241411.','broader_anzsco_2414_context',jsonb_build_object('employment_total',161400,'median_weekly_earnings_aud',2322,'median_hourly_earnings_aud',64,'part_time_share_pct',23,'female_share_pct',58,'median_age',40,'average_full_time_hours',45,'data_as_at','2026-02-01','scope','ANZSCO 2414 Secondary School Teachers unit-group context'),'earnings_scope','No reviewed six-digit earnings observation is used for current OSCA 251331. Broader 2414 earnings are context only, so the salary component is zero.','vacancy_scope','May 2026 IVI three-month-average vacancies are 762.33333 at broader ANZSCO 2414, down from 854 in May 2025, about -10.73% year on year. Vacancy intensity and trend are not credited as exact occupation observations.','projection_scope','JSA broader ANZSCO 2414 projections are +5.45% from May 2025 to May 2030 and +11.68% to May 2035, receiving partial growth credit.','shortage_note','The reviewed JSA 2025 Occupation Shortage List records current OSCA 251331 as a national shortage occupation. Regional shortage is left null rather than inferred from the national result.','visa_basis','The current skilled occupation instrument lists ANZSCO 241411 Secondary School Teacher with AITSL as assessing authority. Migration assessment and teacher registration are separate processes.','registration_basis','School teachers must meet state or territory teacher-registration requirements. Subject teaching areas and other registration requirements can depend on jurisdiction and prior study.','entry_level_basis','Notre Dame Bachelor of Secondary Education 116885E is a four-year professional teacher-education route with school placements. RMIT Master of Teaching Practice (Secondary Education) 113706D is a two-year graduate-entry route with teaching areas determined from prior study.','score_note','Full national shortage and migration credit are supported by exact occupation evidence. Broader labour-market observations are contextual only; broader long-run growth receives partial credit.'),'2026-08-09') on conflict(profile_key,as_of_date) do update set employment_total=excluded.employment_total,median_weekly_earnings=excluded.median_weekly_earnings,median_hourly_earnings=excluded.median_hourly_earnings,annualised_median_salary=excluded.annualised_median_salary,all_occupations_median_weekly=excluded.all_occupations_median_weekly,part_time_share_pct=excluded.part_time_share_pct,female_share_pct=excluded.female_share_pct,median_age=excluded.median_age,average_full_time_hours=excluded.average_full_time_hours,vacancies_three_month_avg=excluded.vacancies_three_month_avg,vacancy_period=excluded.vacancy_period,vacancy_yoy_pct=excluded.vacancy_yoy_pct,employment_growth_5y_pct=excluded.employment_growth_5y_pct,employment_growth_10y_pct=excluded.employment_growth_10y_pct,shortage_component=excluded.shortage_component,vacancy_intensity_component=excluded.vacancy_intensity_component,employer_diversity_component=excluded.employer_diversity_component,vacancy_trend_component=excluded.vacancy_trend_component,entry_level_component=excluded.entry_level_component,salary_component=excluded.salary_component,growth_component=excluded.growth_component,visa_component=excluded.visa_component,entry_burden_component=excluded.entry_burden_component,opportunity_score=excluded.opportunity_score,score_methodology_version=excluded.score_methodology_version,score_status=excluded.score_status,score_evidence=excluded.score_evidence,source_checked_at=excluded.source_checked_at;
